#!/usr/bin/env bash
# Deploy inference-router as a host generation and cut over live (env from the fleet-env projection, or --env-file).
# Build, write a generation directory (binary + rendered host-topology gateway.config.json), start inference-router@<activation>, verify it by its /health body, switch the boot generation, retire the old one (SIGUSR1) and confirm it stopped accepting, prune. A test home (--home other than $HOME) never touches systemd.
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'router/install.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'install.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
set -euo pipefail

SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
TEMPLATE="$SCRIPT_DIR/inference-router@.service.in"
WG_TEMPLATE="$SCRIPT_DIR/inference-router-wg.socket.in"
STATIC_UNITS="inference-router.socket inference-router-hold.service"
CATALOG="$SCRIPT_DIR/catalog/catalog.json"
HEALTH_BASE="${INFERENCE_ROUTER_HEALTH_BASE:-http://127.0.0.1:4813}"
VERIFY_TRIES="${INFERENCE_ROUTER_VERIFY_TRIES:-60}"
RETIRE_ACK_TRIES="${INFERENCE_ROUTER_RETIRE_ACK_TRIES:-150}"
INSTALL_HOME="${INFERENCE_ROUTER_INSTALL_HOME:-$HOME}"
RUST_BIN="${INFERENCE_ROUTER_RUST_BIN:-}"
ENV_FILE_ARG=""
ROLLBACK=0
PREFLIGHT=0

usage() {
  cat <<'USAGE'
usage: install.sh [--env-file <path>] [--home <dir>] [--rust-bin <path>] [--rollback]
                  [--preflight]

  Deploys a new inference-router host generation and cuts over live, end to end:
   1. builds gateway/ in release from this checkout (or takes --rust-bin);
   2. renders the node's host topology: the committed config named by
      INFERENCE_ROUTER_CONFIG_FILE in the projected env file (else gateway.config.json),
      with exactly two upstream rewrites (inference-engine-llama:4806 -> 127.0.0.1:4811,
      host.docker.internal:4877 -> 127.0.0.1:4877); any other container-only host in a
      provider baseurl is an install error;
   3. writes <home>/.local/lib/inference-router/generations/<activation>/ (the binary
      and the rendered gateway.config.json) and renders inference-router@.service,
      inference-router.socket (127.0.0.1:4813), inference-router-hold.service and, only
      when the env file carries INFERENCE_ROUTER_WG_BIND_ADDRESS, inference-router-wg.socket
      (a wildcard address is refused);
   4. (real home) starts the sockets, starts inference-router@<activation>, polls /health
      until that activation id answers; a failed verify retires the new generation and
      leaves the old one serving;
   5. enables the new generation, sends every older generation SIGUSR1 (retire) and waits
      for its acknowledgment (StatusText "retiring", or the unit already gone);
   6. keeps the current and previous generation directories, prunes the rest.
  When the running generation refuses the projected INFERENCE_ROUTER_GATEWAY_KEY, the
  switch is reported as a key rotation (a short failure window), not a zero-failure cutover.

  --env-file <path> The env file the unit reads (default: the fleet-env projection
                    $XDG_RUNTIME_DIR/fleet-env/inference-router.env). Missing = error.
  --home <dir>      Install under <dir> instead of $HOME (also INFERENCE_ROUTER_INSTALL_HOME).
                    A non-default home writes files only: no systemctl/loginctl/curl.
  --rust-bin <path> Install this prebuilt binary instead of building (no toolchain needed).
  --rollback        Start a new generation from the previous generation's directory
                    (its binary and rendered config); no build.
  --preflight       Render and print the topology (source config, listen addresses,
                    provider upstreams); change nothing.
USAGE
}

die() { printf 'install.sh: %s\n' "$*" >&2; exit 1; }

# shellcheck source=/dev/null
. "$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")/../scripts/lib/build-id.sh"
build_flags "${BASH_SOURCE[0]}" "$@"

while [ $# -gt 0 ]; do
  case "$1" in
    --home) [ $# -ge 2 ] || die "--home requires a directory argument"; INSTALL_HOME="$2"; shift 2 ;;
    --home=*) INSTALL_HOME="${1#--home=}"; shift ;;
    --rust-bin) [ $# -ge 2 ] || die "--rust-bin requires a path argument"; RUST_BIN="$2"; shift 2 ;;
    --rust-bin=*) RUST_BIN="${1#--rust-bin=}"; shift ;;
    --env-file) [ $# -ge 2 ] || die "--env-file requires a path argument"; ENV_FILE_ARG="$2"; shift 2 ;;
    --env-file=*) ENV_FILE_ARG="${1#--env-file=}"; shift ;;
    --rollback) ROLLBACK=1; shift ;;
    --preflight) PREFLIGHT=1; shift ;;
    -h|--help) usage; exit 0 ;;
    *) usage >&2; die "unknown argument: $1" ;;
  esac
done

[ -n "$INSTALL_HOME" ] || die "install home resolves to an empty path"
[ -f "$TEMPLATE" ] || die "missing unit template: $TEMPLATE"
[ -z "$RUST_BIN" ] || [ -x "$RUST_BIN" ] || die "--rust-bin is not an executable file: $RUST_BIN"
[ "$ROLLBACK" -eq 0 ] || [ -z "$RUST_BIN" ] || die "--rollback takes the previous generation's binary; drop --rust-bin"
command -v perl >/dev/null 2>&1 || die "perl not found (the topology render uses perl + JSON::PP)"

# --- the env file (projection) ---------------------------------------------------------
if [ -n "$ENV_FILE_ARG" ]; then
  ENV_FILE="$ENV_FILE_ARG"
  UNIT_ENV_FILE="$ENV_FILE_ARG"
else
  ENV_FILE="${XDG_RUNTIME_DIR:-/run/user/$(id -u)}/fleet-env/inference-router.env"
  UNIT_ENV_FILE='%t/fleet-env/inference-router.env'
fi
case "$ENV_FILE" in /*) ;; *) die "--env-file must be an absolute path: $ENV_FILE" ;; esac
case "$ENV_FILE" in *[!A-Za-z0-9._/@:+,=%-]*) die "env file path has unsupported characters: $ENV_FILE" ;; esac
[ -f "$ENV_FILE" ] || die "projected env file is missing: $ENV_FILE (run fleet-env project, or pass --env-file)"

env_value() { # <key>: the last KEY= value in the env file; empty when absent
  sed -n "s/^$1=//p" -- "$ENV_FILE" | tail -n 1 | sed -e 's/^"\(.*\)"$/\1/' -e "s/^'\(.*\)'$/\1/"
}
env_has() { grep -q "^$1=" -- "$ENV_FILE"; }

GATEWAY_KEY="$(env_value INFERENCE_ROUTER_GATEWAY_KEY)"
[ -n "$GATEWAY_KEY" ] || env_has AUTH_STATIC_API_KEYS || die "$ENV_FILE carries no INFERENCE_ROUTER_GATEWAY_KEY (client auth is always on)"

SRC_CONFIG_REL="$(env_value INFERENCE_ROUTER_CONFIG_FILE)"
if [ -n "$SRC_CONFIG_REL" ]; then
  case "$SRC_CONFIG_REL" in
    /*) SRC_CONFIG="$SRC_CONFIG_REL" ;;
    *) SRC_CONFIG="$SCRIPT_DIR/${SRC_CONFIG_REL#router/}" ;;
  esac
else
  SRC_CONFIG="$SCRIPT_DIR/gateway.config.json"
fi
[ -f "$SRC_CONFIG" ] || die "node config not found: $SRC_CONFIG"

# --- listen addresses -------------------------------------------------------------------
SOCKETS="inference-router.socket"
LISTEN="127.0.0.1:4813"
WG_LISTEN=""
if env_has INFERENCE_ROUTER_WG_BIND_ADDRESS; then
  wg="$(env_value INFERENCE_ROUTER_WG_BIND_ADDRESS)"
  case "$wg" in
    ''|0.0.0.0|'::'|'[::]'|'*'|:*) die "INFERENCE_ROUTER_WG_BIND_ADDRESS='$wg' is a wildcard or empty address; name the node's WireGuard address" ;;
  esac
  case "$wg" in *[!0-9A-Fa-f.:]*) die "INFERENCE_ROUTER_WG_BIND_ADDRESS='$wg' is not an IP address" ;; esac
  case "$wg" in
    *:*) WG_LISTEN="[$wg]:4813" ;;
    *) WG_LISTEN="$wg:4813" ;;
  esac
  SOCKETS="$SOCKETS inference-router-wg.socket"
  LISTEN="$LISTEN $WG_LISTEN"
fi

# --- the topology render (perl + JSON::PP; no python/node/jq) ----------------------------
render() { # <source config> -> rendered JSON on stdout; topology lines on stderr
  perl -MJSON::PP -e '
    my ($path) = @ARGV;
    open(my $fh, "<", $path) or die "read $path: $!\n";
    local $/; my $raw = <$fh>; close $fh;
    my $cfg = JSON::PP->new->decode($raw);
    my %rewrite = ("inference-engine-llama:4806" => "127.0.0.1:4811",
                   "host.docker.internal:4877" => "127.0.0.1:4877");
    for my $p (@{ $cfg->{providers} || [] }) {
      my $u = $p->{baseurl} // next;
      my ($scheme, $host, $port, $rest) = $u =~ m{^(https?)://(\[[^\]]+\]|[^/:]+)(?::(\d+))?(.*)$}
        or die "provider $p->{name}: unparseable baseurl $u\n";
      my $hp = defined $port ? "$host:$port" : $host;
      if (exists $rewrite{$hp}) {
        $p->{baseurl} = "$scheme://$rewrite{$hp}$rest";
      } elsif ($host =~ /^(127\.\d+\.\d+\.\d+|localhost|\[::1\])$/) {
      } elsif ($host eq "host.docker.internal" || $host eq "inference-engine-llama" || $host !~ /\./) {
        die "provider $p->{name}: container-only upstream $hp in $u (only inference-engine-llama:4806 and host.docker.internal:4877 are rewritten)\n";
      }
      print STDERR "upstream $p->{name} $p->{baseurl}\n";
    }
    print JSON::PP->new->pretty->canonical->encode($cfg);
  ' "$1"
}

if [ "$PREFLIGHT" -eq 1 ]; then
  printf 'source  %s\n' "$SRC_CONFIG"
  printf 'env     %s\n' "$ENV_FILE"
  printf 'listen  %s\n' "$LISTEN"
  { render "$SRC_CONFIG" >/dev/null; } 2>&1 || die "topology render failed for $SRC_CONFIG"
  printf 'preflight: nothing written\n'
  exit 0
fi

REAL_HOME=0
[ "$INSTALL_HOME" != "${HOME:-}" ] || REAL_HOME=1

# --- generation directory -------------------------------------------------------------------
LIB_DIR="$INSTALL_HOME/.local/lib/inference-router"
GEN_ROOT="$LIB_DIR/generations"
ACTIVATION="$(date -u +%Y%m%dT%H%M%SZ)-$(od -An -N4 -tx1 /dev/urandom | tr -d ' \n')"
GEN_DIR="$GEN_ROOT/$ACTIVATION"
PREVIOUS="$(cat -- "$LIB_DIR/current" 2>/dev/null || true)"

mkdir -p -- "$GEN_ROOT"
tmp_gen="$(mktemp -d -- "$GEN_ROOT/.new.XXXXXX")"
trap 'rm -rf -- "$tmp_gen"' EXIT
if [ "$ROLLBACK" -eq 1 ]; then
  rb="$(cat -- "$LIB_DIR/previous" 2>/dev/null || true)"
  [ -n "$rb" ] || die "--rollback: no previous generation recorded in $LIB_DIR/previous"
  for f in inference-router gateway.config.json; do
    [ -f "$GEN_ROOT/$rb/$f" ] || die "--rollback: previous generation $rb lacks $f"
  done
  src_bin="$GEN_ROOT/$rb/inference-router"
  cp -- "$GEN_ROOT/$rb/gateway.config.json" "$tmp_gen/gateway.config.json"
  printf 'build   skipped: rollback to generation %s\n' "$rb"
else
  if ! render "$SRC_CONFIG" > "$tmp_gen/gateway.config.json" 2> "$tmp_gen/render.err"; then
    die "topology render failed: $(tail -n 1 -- "$tmp_gen/render.err")"
  fi
  rm -f -- "$tmp_gen/render.err"
  src_bin="$RUST_BIN"
  if [ -z "$src_bin" ]; then
    command -v cargo >/dev/null 2>&1 || die "cargo not found; needed to build the router (or pass --rust-bin)"
    cargo build --release --manifest-path "$SCRIPT_DIR/gateway/Cargo.toml" >&2 \
      || die "cargo build --release --manifest-path $SCRIPT_DIR/gateway/Cargo.toml failed"
    src_bin="$SCRIPT_DIR/gateway/target/release/inference-router"
    printf 'build   cargo build --release --manifest-path %s/gateway/Cargo.toml\n' "$SCRIPT_DIR"
  else
    printf 'build   skipped: prebuilt %s\n' "$src_bin"
  fi
fi
[ -x "$src_bin" ] || die "rust binary not found or not executable: $src_bin"
cp -- "$src_bin" "$tmp_gen/inference-router"
chmod 0755 -- "$tmp_gen/inference-router" "$tmp_gen"
chmod 0644 -- "$tmp_gen/gateway.config.json"
mv -T -- "$tmp_gen" "$GEN_DIR"
trap - EXIT
printf 'gen     %s (activation %s)\n' "$GEN_DIR" "$ACTIVATION"
printf 'source  %s\n' "$SRC_CONFIG"
printf 'listen  %s\n' "$LISTEN"
mkdir -p -- "$INSTALL_HOME/.local/state/inference-router/logs"

# --- render the units -----------------------------------------------------------------------
UNIT_DIR="$INSTALL_HOME/.config/systemd/user"
if [ -n "$ENV_FILE_ARG" ]; then
  unit_deps=(-e '/^@FLEET_ENV_UNIT@$/d')
else
  unit_deps=(-e 's|^@FLEET_ENV_UNIT@$|After=fleet-env-project.service\nRequires=fleet-env-project.service|')
fi

put_unit() { # <name> <content>
  local file="$UNIT_DIR/$1" state
  if [ -f "$file" ] && [ "$2" = "$(cat -- "$file")" ]; then
    state="unchanged"
  else
    if [ -f "$file" ]; then state="updated"; else state="created"; fi
    printf '%s\n' "$2" > "$file"
    chmod 0644 -- "$file"
  fi
  printf 'unit    %s (%s)\n' "$file" "$state"
}

mkdir -p -- "$UNIT_DIR"
put_unit "inference-router@.service" "$(sed \
  "${unit_deps[@]}" \
  -e "s|@ENV_FILE@|$UNIT_ENV_FILE|g" \
  -e "s|@LIB_DIR@|$LIB_DIR|g" \
  -e "s|@CATALOG@|$CATALOG|g" \
  -e "s|@SOCKETS@|$SOCKETS|g" \
  -- "$TEMPLATE")"
for u in $STATIC_UNITS; do
  put_unit "$u" "$(cat -- "$SCRIPT_DIR/$u")"
done
if [ -n "$WG_LISTEN" ]; then
  put_unit "inference-router-wg.socket" "$(sed -e "s|@WG_LISTEN@|$WG_LISTEN|g" -- "$WG_TEMPLATE")"
elif [ -f "$UNIT_DIR/inference-router-wg.socket" ]; then
  rm -f -- "$UNIT_DIR/inference-router-wg.socket"
  printf 'unit    %s (removed: no INFERENCE_ROUTER_WG_BIND_ADDRESS)\n' "$UNIT_DIR/inference-router-wg.socket"
fi

prune() { # <keep...>: keep the current and previous generation (and any still running)
  local d name k keep
  for d in "$GEN_ROOT"/*/; do
    [ -d "$d" ] || continue
    name="$(basename -- "$d")"
    keep=0
    for k in "$@"; do [ "$name" != "$k" ] || keep=1; done
    if [ "$keep" -eq 0 ] && [ "$REAL_HOME" -eq 1 ] &&
      systemctl --user is-active --quiet "inference-router@$name.service" 2>/dev/null; then
      keep=1
    fi
    if [ "$keep" -eq 0 ]; then
      rm -rf -- "$d"
      printf 'prune   generation %s\n' "$name"
    fi
  done
}

record() { # the verified boot generation and its predecessor (the validator reads current)
  if [ -n "$PREVIOUS" ] && [ "$PREVIOUS" != "$ACTIVATION" ]; then
    printf '%s\n' "$PREVIOUS" > "$LIB_DIR/previous"
  fi
  printf '%s\n' "$ACTIVATION" > "$LIB_DIR/current"
}

if [ "$REAL_HOME" -ne 1 ]; then
  record
  prune "$ACTIVATION" "$PREVIOUS"
  printf 'systemd skipped: --home %s is not the current HOME (test render; nothing started, retired or enabled)\n' "$INSTALL_HOME"
  exit 0
fi

# --- live cutover (real home) -------------------------------------------------------------------
command -v systemctl >/dev/null 2>&1 || die "systemctl not found"
command -v curl >/dev/null 2>&1 || die "curl not found (the verify reads /health)"
sc() { systemctl --user "$@"; }

sc daemon-reload
printf 'reload  systemctl --user daemon-reload: done\n'
# Sockets before the hold unit: systemd refuses to start a socket whose Service= unit is
# already active ("Socket service ... already active, refusing"). A socket that is not yet
# listening (first install, or the WireGuard socket added later) therefore needs the hold
# unit stopped first; generations keep their inherited sockets across that.
for s in $SOCKETS; do
  if ! sc is-active --quiet "$s" 2>/dev/null; then
    sc stop inference-router-hold.service 2>/dev/null || true
    break
  fi
done
if [ -n "$WG_LISTEN" ]; then
  sc enable --now inference-router.socket inference-router-wg.socket
else
  sc disable --now inference-router-wg.socket >/dev/null 2>&1 || true
  sc enable --now inference-router.socket
fi
sc start inference-router-hold.service
printf 'sockets %s active\n' "$SOCKETS"

mapfile -t OLD < <(sc list-units --plain --no-legend --state=active,activating,reloading \
  'inference-router@*.service' | awk '{print $1}' | grep -vx "inference-router@$ACTIVATION.service" || true)

# Admission: two generations overlap safely only when both accept the same key.
if [ "${#OLD[@]}" -gt 0 ] && [ -n "$GATEWAY_KEY" ]; then
  pre="$(curl -sS --max-time 3 -o /dev/null -w '%{http_code}' -H "x-gateway-key: ${GATEWAY_KEY}" "$HEALTH_BASE/v1/models" 2>/dev/null || true)"
  if [ "$pre" = "401" ]; then
    printf 'KEY ROTATION: the running generation refuses the projected INFERENCE_ROUTER_GATEWAY_KEY. This switch is a key rotation with a short failure window (clients holding the old key fail until they carry the new one), not a zero-failure cutover.\n' >&2
  fi
fi

NEW_UNIT="inference-router@$ACTIVATION.service"
fail_new() {
  printf 'install.sh: %s; retiring %s, the old generation keeps serving\n' "$1" "$NEW_UNIT" >&2
  sc kill -s SIGUSR1 --kill-whom=main "$NEW_UNIT" 2>/dev/null || sc stop "$NEW_UNIT" 2>/dev/null || true
  rm -rf -- "$GEN_DIR"
  exit 1
}

# Type=notify: `start` returns once the generation's startup checks passed (READY=1).
sc start "$NEW_UNIT" || fail_new "systemctl --user start $NEW_UNIT failed"
verified=0
for _ in $(seq 1 "$VERIFY_TRIES"); do
  body="$(curl -sS --max-time 3 "$HEALTH_BASE/health" 2>/dev/null || true)"
  case "$body" in
    *'"activation":"'"$ACTIVATION"'"'*)
      case "$body" in *'"status":"ok"'*) verified=1; break ;; esac ;;
  esac
  sleep 0.5
done
[ "$verified" -eq 1 ] || fail_new "verify: /health never answered ok from activation $ACTIVATION"
printf 'verify  /health answered ok from activation %s\n' "$ACTIVATION"

sc enable "$NEW_UNIT" >/dev/null 2>&1
for u in "${OLD[@]+"${OLD[@]}"}"; do sc disable "$u" >/dev/null 2>&1 || true; done
record
printf 'boot    %s enabled\n' "$NEW_UNIT"

rc=0
for u in "${OLD[@]+"${OLD[@]}"}"; do
  sc kill -s SIGUSR1 --kill-whom=main "$u"
  acked=0
  for _ in $(seq 1 "$RETIRE_ACK_TRIES"); do
    if ! sc is-active --quiet "$u" 2>/dev/null; then acked=1; break; fi
    if [ "$(sc show -p StatusText --value "$u" 2>/dev/null)" = "retiring" ]; then acked=1; break; fi
    sleep 0.2
  done
  if [ "$acked" -eq 1 ]; then
    printf 'retire  %s stopped accepting (finishing in-flight requests, then exits 0)\n' "$u"
  else
    printf 'install.sh: %s did not acknowledge SIGUSR1; it may still accept\n' "$u" >&2
    rc=1
  fi
done

prune "$ACTIVATION" "$PREVIOUS"

if command -v loginctl >/dev/null 2>&1 &&
  [ "$(loginctl show-user "${USER:-$(id -un)}" -p Linger --value 2>/dev/null || true)" != "yes" ]; then
  printf 'linger  NOT enabled: the generation will not start at boot (loginctl enable-linger %s)\n' "${USER:-$(id -un)}"
fi
exit "$rc"
